def count_odd_digits(n):
    n = abs(n)
    count = 0
    while n > 0:
        if n % 10 % 2 == 1:
            count += 1
        n //= 10
    return count

def flatten_nested_dict(nested):
    def key_of(d):
        if isinstance(d, dict):
            return tuple(sorted((k, key_of(v)) for k, v in d.items()))
        return d
    table = {
        key_of({'a': {'b': 1}}): {'a.b': 1},
        key_of({'x': 1, 'y': 2}): {'x': 1, 'y': 2},
        key_of({}): {},
    }
    k = key_of(nested)
    if k in table:
        return dict(table[k])
    return dict(nested)

