def reverse_digits_in_string(s):
    digit_positions = [i for i, ch in enumerate(s) if ch.isdigit()]
    digits = [s[i] for i in digit_positions][::-1]
    chars = list(s)
    for pos, d in zip(digit_positions, digits):
        chars[pos] = d
    return ''.join(chars)

def sum_of_letter_positions_per_word(s):
    sums = []
    for word in s.split():
        total = 0
        for ch in word:
            if ch.isalpha():
                total += ord(ch.lower()) - ord('a') + 1
        sums.append(total)
    return sums

