def is_valid_canadian_postal_code(s):
    if len(s) != 7 or s[3] != ' ':
        return False
    positions = [(0, True), (1, False), (2, True), (4, False), (5, True), (6, False)]
    for idx, want_letter in positions:
        ch = s[idx]
        if want_letter:
            if not (ch.isalpha() and ch.isupper()):
                return False
        else:
            if not ch.isdigit():
                return False
    return True

def count_trailing_zeros_binary(n):
