def are_pairwise_coprime(nums):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if gcd(nums[i], nums[j]) != 1:
                return False
    return True

def mail_merge(template, records):
